`timescale 1ns / 1ps
`include "params.vh"
`include "data_dir.vh"   // defines DATA_DIR: absolute path to rtl/ on THIS machine.
                         // Generated by scripts/create_project.tcl (not committed).
// ============================================================================
// tb_mlp_core.v -- end-to-end testbench: pixels in, digit out
//
// PHASE 1  one image at a time, the 64 golden images. Checks every stage's
//          output against golden.txt: the 32 hidden values (hq), the 10
//          scores (acc2), and the predicted digit. Also checks latency is
//          exactly 832 cycles, done is a single pulse, busy stays high the
//          whole time, and that stray start pulses are ignored -- including
//          ones that arrive while layer 2 or argmax are running, when layer 1
//          itself is idle and would otherwise accept them.
//
// PHASE 2  all 100 test images streamed back-to-back with start held high,
//          the way a real image source would drive it. Checks the golden
//          predictions still match, reports the cycles between results
//          (throughput), and reports classification accuracy against the
//          true labels -- the number the on-board run should reproduce.
// ============================================================================

module tb_mlp_core;

    localparam N_IN    = `N_IN;
    localparam N_H     = `N_HIDDEN;
    localparam N_O     = `N_OUT;
    localparam ACC_W   = `ACC_W;
    localparam N_GOLD  = 64;
    localparam N_ALL   = 100;
    localparam LATENCY = 832;

    reg                     clk = 0, rst = 1, start = 0;
    wire                    busy, done;
    wire [9:0]              pix_addr;
    reg  [7:0]              pix_data = 0;
    wire [3:0]              digit;
    wire [N_O*ACC_W-1:0]    scores;
    wire [N_H*8-1:0]        h;

    mlp_core dut (
        .clk(clk), .rst(rst), .start(start), .busy(busy), .done(done),
        .pix_addr(pix_addr), .pix_data(pix_data),
        .digit(digit), .scores_flat(scores), .h_flat(h)
    );

    always #5 clk = ~clk;

    // ------------------------------------------------ pixel RAM model
    reg [7:0] img [0:N_ALL*N_IN-1];
    integer   base = 0;
    always @(posedge clk) pix_data <= img[base + pix_addr];

    // ------------------------------------------------ golden data
    integer g_pred [0:N_GOLD-1];
    integer g_hq   [0:N_GOLD*N_H-1];
    integer g_acc2 [0:N_GOLD*N_O-1];
    integer label  [0:N_ALL-1];

    integer t, n, gv, rc, fd, got, lat, extra, busy_drops, stray_at;
    integer f_hq = 0, f_sc = 0, f_dig = 0, f_ctl = 0, f_b2b = 0, n_pass = 0;
    integer n_correct = 0, n_done = 0, t_prev = 0, period = 0, period_min = 0, period_max = 0;
    reg [8*16-1:0] tok;

    initial begin
        $display("==== tb_mlp_core ====");
        $readmemh({`DATA_DIR, "test_images.mem"}, img);

        fd = $fopen({`DATA_DIR, "test_labels.txt"}, "r");
        for (t = 0; t < N_ALL; t = t + 1) begin rc = $fscanf(fd, "%d", gv); label[t] = gv; end
        $fclose(fd);

        fd = $fopen({`DATA_DIR, "golden.txt"}, "r");
        if (fd == 0) begin
            $display("FAIL  could not open golden.txt -- check DATA_DIR");
            $finish;
        end
        rc = $fscanf(fd, "%s", tok);
        while (tok != "img") rc = $fscanf(fd, "%s", tok);
        for (t = 0; t < N_GOLD; t = t + 1) begin
            rc = $fscanf(fd, "%d %s %d %s %d", gv, tok, gv, tok, got); g_pred[t] = got;
            rc = $fscanf(fd, "%s", tok);
            for (n = 0; n < N_H; n = n + 1) rc = $fscanf(fd, "%d", gv);          // acc1 (not exposed)
            rc = $fscanf(fd, "%s", tok);
            for (n = 0; n < N_H; n = n + 1) begin rc = $fscanf(fd, "%d", gv); g_hq[t*N_H + n] = gv; end
            rc = $fscanf(fd, "%s", tok);
            for (n = 0; n < N_O; n = n + 1) begin rc = $fscanf(fd, "%d", gv); g_acc2[t*N_O + n] = gv; end
            rc = $fscanf(fd, "%s", tok);
        end
        $fclose(fd);

        repeat (3) @(posedge clk);
        #1 rst = 0;
        @(posedge clk); #1;

        // ============================================ PHASE 1
        for (t = 0; t < N_GOLD; t = t + 1) begin
            base = t * N_IN;
            // stray start: image 0 during layer 1, image 1 during layer 2,
            // image 2 during argmax
            stray_at = (t == 0) ? 100 : (t == 1) ? 800 : (t == 2) ? 826 : -1;
            busy_drops = 0;
            start = 1; @(posedge clk); #1; start = 0;
            lat = 0;
            while (!done && lat < 5000) begin
                if (!busy) busy_drops = busy_drops + 1;
                if (lat == stray_at) start = 1;
                @(posedge clk); #1;
                start = 0;
                lat = lat + 1;
            end
            if (busy) busy_drops = busy_drops + 1;
            // After done the core must stay idle. Where a stray start was
            // thrown in, watch for longer than a full layer-1 run: a stray that
            // sneaked into layer 1 would only surface ~786 cycles later.
            extra = 0;
            repeat ((stray_at >= 0) ? 1000 : 3) begin
                @(posedge clk); #1;
                // peek inside: no stage may be running once the core is done
                if (done || busy || dut.l1_busy || dut.l2_busy || dut.am_busy) extra = extra + 1;
            end
            if (lat != LATENCY || extra != 0 || busy_drops != 0) begin
                f_ctl = f_ctl + 1;
                $display("FAIL  img %0d control: latency=%0d (want %0d) extra=%0d busy_drops=%0d",
                         t, lat, LATENCY, extra, busy_drops);
            end

            for (n = 0; n < N_H; n = n + 1)
                if (h[8*n +: 8] !== g_hq[t*N_H + n]) begin
                    f_hq = f_hq + 1;
                    if (f_hq <= 5) $display("FAIL  img %0d hidden %0d: expected %0d, got %0d",
                                            t, n, g_hq[t*N_H + n], h[8*n +: 8]);
                end else n_pass = n_pass + 1;
            for (n = 0; n < N_O; n = n + 1) begin
                got = $signed(scores[ACC_W*n +: ACC_W]);
                if (got !== g_acc2[t*N_O + n]) begin
                    f_sc = f_sc + 1;
                    if (f_sc <= 5) $display("FAIL  img %0d score %0d: expected %0d, got %0d",
                                            t, n, g_acc2[t*N_O + n], got);
                end else n_pass = n_pass + 1;
            end
            if (digit !== g_pred[t]) begin
                f_dig = f_dig + 1;
                $display("FAIL  img %0d digit: expected %0d, got %0d", t, g_pred[t], digit);
            end else n_pass = n_pass + 1;
        end
        $display("phase 1  : %0d images -- hidden %0d fail, scores %0d fail, digit %0d fail, control %0d fail",
                 N_GOLD, f_hq, f_sc, f_dig, f_ctl);
        $display("           latency %0d cycles = %0d ns per image", LATENCY, LATENCY * 10);

        // ============================================ PHASE 2
        // start held high: the core restarts in the same cycle it finishes.
        base   = 0;
        n_done = 0;
        start  = 1;
        t_prev = $time;
        while (n_done < N_ALL) begin
            @(posedge clk); #1;
            if (done) begin
                if (n_done > 0) begin
                    period = ($time - t_prev) / 10;
                    if (n_done == 1 || period < period_min) period_min = period;
                    if (n_done == 1 || period > period_max) period_max = period;
                end
                t_prev = $time;
                if (digit == label[n_done]) n_correct = n_correct + 1;
                if (n_done < N_GOLD) begin
                    if (digit !== g_pred[n_done]) begin
                        f_b2b = f_b2b + 1;
                        $display("FAIL  streamed img %0d digit: expected %0d, got %0d",
                                 n_done, g_pred[n_done], digit);
                    end else n_pass = n_pass + 1;
                end
                n_done = n_done + 1;
                base   = n_done * N_IN;      // next image; layer 1 starts reading after this edge
            end
        end
        start = 0;
        $display("phase 2  : %0d images streamed, %0d golden predictions fail", N_ALL, f_b2b);
        $display("           %0d cycles between results -> %0d images/s at 100 MHz",
                 period_max, 100000000 / period_max);
        if (period_min != period_max) begin
            f_b2b = f_b2b + 1;
            $display("FAIL  uneven streaming period: %0d..%0d cycles", period_min, period_max);
        end
        $display("ACCURACY : %0d / %0d test images classified correctly", n_correct, N_ALL);

        $display("================================");
        if (f_hq + f_sc + f_dig + f_ctl + f_b2b == 0)
            $display("ALL TESTS PASSED  (%0d checks)", n_pass + N_GOLD);
        else
            $display("%0d CHECKS FAILED", f_hq + f_sc + f_dig + f_ctl + f_b2b);
        $display("================================");
        $finish;
    end

endmodule
